const DojoMedia=(function(){
 const temporary=new Map(),urls=new Set();let connection;
 function open(){if(!window.indexedDB)return Promise.reject(new Error('Armazenamento de arquivos indisponível'));return connection||=(new Promise((resolve,reject)=>{const request=indexedDB.open('san-dojo-media-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('assets');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Feche outras abas do aplicativo e tente novamente.'));}));}
 async function put(key,blob){try{const db=await open();await new Promise((resolve,reject)=>{const tx=db.transaction('assets','readwrite');tx.objectStore('assets').put(blob,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});temporary.delete(key);return true;}catch(error){temporary.set(key,blob);return false;}}
 async function get(key){if(temporary.has(key))return temporary.get(key);try{const db=await open();return await new Promise((resolve,reject)=>{const r=db.transaction('assets').objectStore('assets').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}catch{return null;}}
 async function remove(key){temporary.delete(key);try{const db=await open();await new Promise((resolve,reject)=>{const tx=db.transaction('assets','readwrite');tx.objectStore('assets').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch{}}
 function url(blob){const src=URL.createObjectURL(blob);urls.add(src);return src;}
 function clearUrls(){for(const u of urls)URL.revokeObjectURL(u);urls.clear();}
 return {put,get,remove,url,clearUrls};
})();
function parseYouTube(raw){try{const u=new URL(raw);if(u.protocol!=='https:')return null;const host=u.hostname.toLowerCase();let id;if(host==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com','youtube-nocookie.com'].includes(host)){if(u.pathname==='/watch')id=u.searchParams.get('v');else if(/^\/(embed|shorts|live)\//.test(u.pathname))id=u.pathname.split('/')[2];}return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:null;}catch{return null;}}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function diagram(type){
 const wrap=(body,label)=>`<figure class="movement-diagram"><svg viewBox="0 0 500 210" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg"><rect width="500" height="210" rx="16" fill="#f6f6f6"/>${body}</svg><figcaption>${label} · esquema de apoio, sem escala. A execução é orientada pelo sensei.</figcaption></figure>`;
 const foot=(x,y,r=0)=>`<g transform="translate(${x} ${y}) rotate(${r})"><path d="M-10 25Q-14 7-9-13Q-7-28 4-29Q17-28 16-12L10 26Z" fill="#222"/><circle cy="-18" cx="3" r="3" fill="#fff"/></g>`;
 if(type==='levels')return wrap(`<circle cx="160" cy="40" r="21" fill="#222"/><path d="M134 70H186L194 132H126Z" fill="#ddd" stroke="#222" stroke-width="3"/><path d="M133 76L107 123M185 76L210 123M144 132L132 190M177 132L191 190" stroke="#222" stroke-width="15" stroke-linecap="round"/><path d="M214 40H275M214 98H275M214 158H275" stroke="#d8222c" stroke-width="2" stroke-dasharray="5 5"/><text x="294" y="46" font-size="18" font-family="sans-serif" fill="#222">1 · Região alta</text><text x="294" y="104" font-size="18" font-family="sans-serif" fill="#222">2 · Região média</text><text x="294" y="164" font-size="18" font-family="sans-serif" fill="#222">3 · Região baixa</text>`,'Três níveis de altura');
 if(type==='kiba')return wrap(`${foot(186,100)}${foot(314,100)}<path d="M215 100H285" stroke="#d8222c" stroke-width="3"/><text x="250" y="175" text-anchor="middle" font-family="sans-serif" font-size="17" fill="#555">Organização lateral dos pés</text>`,'Vista esquemática dos pés em base lateral');
 if(type==='bases')return wrap(`${foot(70,100)}${foot(155,100)}${foot(274,63)}${foot(241,137)}${foot(401,81,12)}${foot(434,112,-12)}<path d="M190 35V165M345 35V165" stroke="#ddd"/><text x="112" y="188" text-anchor="middle" font-size="15" font-family="sans-serif">Lateral</text><text x="259" y="188" text-anchor="middle" font-size="15" font-family="sans-serif">Avançada</text><text x="417" y="188" text-anchor="middle" font-size="15" font-family="sans-serif">Compacta</text>`,'Comparação de organizações gerais dos pés');
 if(type==='ido')return wrap(`<rect x="25" y="65" width="120" height="75" rx="14" fill="#fff" stroke="#ddd"/><rect x="190" y="65" width="120" height="75" rx="14" fill="#fff" stroke="#ddd"/><rect x="355" y="65" width="120" height="75" rx="14" fill="#fff" stroke="#ddd"/><text x="85" y="110" text-anchor="middle" font-size="20" font-family="sans-serif">Base</text><text x="250" y="110" text-anchor="middle" font-size="20" font-family="sans-serif">Técnica</text><text x="415" y="110" text-anchor="middle" font-size="20" font-family="sans-serif">Direção</text><path d="M150 100H180L173 94M180 100L173 106M315 100H345L338 94M345 100L338 106" stroke="#d8222c" stroke-width="3"/>`,'Os três aspectos de uma combinação em deslocamento');
 if(type==='kata')return wrap(`<path d="M60 105H440" stroke="#ddd" stroke-width="4"/><circle cx="80" cy="105" r="28" fill="#222"/><circle cx="250" cy="105" r="28" fill="#d8222c"/><circle cx="420" cy="105" r="28" fill="#222"/><g fill="#fff" font-family="sans-serif" font-size="22" text-anchor="middle"><text x="80" y="113">1</text><text x="250" y="113">2</text><text x="420" y="113">3</text></g><g fill="#555" font-family="sans-serif" font-size="16" text-anchor="middle"><text x="80" y="167">Ordem</text><text x="250" y="167">Direção</text><text x="420" y="167">Técnica</text></g>`,'O que observar ao estudar um kata; não é o trajeto do kata');
 return '';
}
function mediaMarkup(phaseId){const found=mediaTarget(phaseId);if(!found)return '';const own=state.media[phaseId]||{},video=own.youtubeId||(!own.videoKey?found.module.video:null);return `<section class="phase-media"><div class="section-head"><h3>${esc(own.title||'Observe com atenção')}</h3><small>${own.youtubeId||own.videoKey||own.imageKey?'MATERIAL DO SENSEI':'REFERÊNCIA DE ESTUDO'}</small></div>${own.description?`<p>${esc(own.description)}</p>`:''}${own.imageKey?`<figure class="own-image"><img data-image-key="${esc(own.imageKey)}" alt="${esc(own.title||'Imagem de apoio do sensei')}"><figcaption data-media-status>Carregando imagem…</figcaption></figure>`:diagram(found.phase.diagram||found.module.diagram)}${own.videoKey?`<video controls playsinline preload="metadata" data-video-key="${esc(own.videoKey)}" aria-label="${esc(own.title||'Vídeo do sensei')}"></video><p data-media-status>Carregando vídeo deste navegador…</p>`:video?`<div class="yt-placeholder"><span>▶</span><h3>${own.youtubeId?'Seu vídeo de treino':'Demonstração · IMAC Dojo'}</h3><p>${own.youtubeId?'Material selecionado pelo sensei.':'Referência de Shinkyokushin em outro idioma. Observe junto com o sensei.'}</p><button class="outline" data-load-video="${video}">Carregar vídeo nesta fase</button></div><a class="external-video" href="https://www.youtube.com/watch?v=${video}" target="_blank" rel="noopener">Abrir vídeo no YouTube ↗</a><small class="video-note">Se o player não abrir no arquivo local, use o link do YouTube. Reprodução depende da internet e da disponibilidade do vídeo.</small>`:''}</section>`;}
async function hydrateMedia(container){for(const node of container.querySelectorAll('[data-image-key],[data-video-key]')){const key=node.dataset.imageKey||node.dataset.videoKey;if(key.startsWith('cloud:')){try{const src=await DojoAccounts.signedUrl(key.slice(6));if(node.isConnected){node.src=src;const status=node.parentElement.querySelector('[data-media-status]');if(status)status.textContent='Material do San Dojo, disponível para sua conta.';}}catch{const status=node.parentElement.querySelector('[data-media-status]');if(status)status.textContent='Não foi possível carregar o material. Atualize a página ou entre novamente.';}continue;}const blob=await DojoMedia.get(key);if(!node.isConnected)continue;const status=node.parentElement.querySelector('[data-media-status]');if(blob){node.src=DojoMedia.url(blob);if(status)status.textContent='Arquivo carregado deste navegador.';}else if(status)status.textContent='Arquivo indisponível aqui. Adicione-o novamente na Biblioteca do sensei.';}}
let libraryModule='dojo',libraryPhase='dojo-1';
function library(){if(!DojoAccounts.canManage())return readOnlyLibrary();const m=mediaGroupById(libraryModule)||C.COURSE[0];return `<section class="animate-in"><div class="eyebrow">BIBLIOTECA DO SENSEI</div><h1>Seu jeito de ensinar, em cada fase</h1><p class="intro">Adicione seus vídeos e imagens e acompanhe as conferências práticas.</p><div class="info-panel library-help"><h2>Como adicionar seus próprios vídeos</h2><ol><li>Escolha o módulo e a fase, uma categoria de Kihon e a técnica (ou categoria inteira), ou o Catálogo de katas e o nome do kata.</li><li>Cole um link do YouTube ou escolha um arquivo MP4/WebM. Se quiser, adicione também uma foto ou imagem.</li><li>Toque em <b>Salvar material</b>. O conteúdo aparece no módulo, no material da técnica de kihon ou no kata escolhido.</li></ol><p><b>Materiais são salvos na biblioteca online do San Dojo.</b> Somente sua conta de administrador pode alterar o conteúdo; os alunos autenticados podem assistir. A exportação abaixo contém links e observações.</p></div><form class="info-panel media-form" id="media-form"><h2>Adicionar ou atualizar material</h2><div class="form-grid"><label>Módulo<select id="media-module">${mediaGroups().map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${x.level}. ${x.title}</option>`).join('')}</select></label><label>Fase<select id="media-phase">${m.phases.map((p,i)=>`<option value="${p.id}" ${p.id===libraryPhase?'selected':''}>${i+1}. ${p.title}</option>`).join('')}</select></label></div><label>Título do material<input id="media-title" maxlength="80" placeholder="Ex.: Minha demonstração de zenkutsu dachi"></label><label>Link do YouTube<input id="media-youtube" type="url" placeholder="https://www.youtube.com/watch?v=..."></label><div class="form-grid"><label>Ou um vídeo do dispositivo<input id="media-video" type="file" accept="video/mp4,video/webm,.mp4,.webm"><small>MP4 ou WebM, até 250 MB.</small></label><label>Imagem de apoio (opcional)<input id="media-image" type="file" accept="image/png,image/jpeg,image/webp,.png,.jpg,.jpeg,.webp"><small>PNG, JPG ou WebP, até 12 MB.</small></label></div><label>O que observar neste material<textarea id="media-description" rows="3" maxlength="300" placeholder="Ex.: Observe a base e depois compare com a correção feita na aula."></textarea></label><button class="primary" type="submit">Salvar material <span>→</span></button><p id="media-form-status" role="status"></p></form><div class="info-panel"><h2>Seus materiais salvos</h2>${Object.entries(state.media).filter(([id])=>mediaTarget(id)).map(([id,v])=>`<article class="saved-media"><div><b>${esc(v.title||'Material do sensei')}</b><small>${esc(mediaTarget(id).module.title)} · ${esc(mediaTarget(id).phase.title)}</small><p>${v.youtubeId?'Link do YouTube':''}${v.videoKey?'Vídeo do dispositivo':''}${v.imageKey?' · Imagem de apoio':''}${v.sessionOnly?' · Arquivo disponível apenas nesta sessão':''}</p></div><button type="button" class="text-button" data-preview-material="${id}">Ver material</button><button type="button" class="text-button" data-remove-material="${id}">Remover</button></article>`).join('')||'<p>Seus materiais aparecerão aqui depois de salvar.</p>'}<div id="remove-material-confirm"></div><div class="library-backup"><button class="outline" data-export-links>Exportar links (.json)</button><label class="outline import-label">Importar links<input id="import-links" type="file" accept="application/json,.json"></label></div><p class="week-note">A exportação inclui títulos, observações e links do YouTube. Vídeos e imagens enviados como arquivo precisam ser adicionados separadamente em outro navegador.</p></div>${trainingCheck()}${senseiChecks()}<div class="info-panel"><h2>Sobre os materiais de referência</h2><p>Os vídeos iniciais são referências externas publicadas pelo IMAC Dojo, Shinkyokushin Thailand. Você pode substituí-los por suas próprias demonstrações em cada fase. Os esquemas do app são apoios de memória e não uma avaliação de movimento.</p>${C.REFERENCES.map(r=>`<p><a href="${r.url}" target="_blank" rel="noopener">${r.name} ↗</a></p>`).join('')}</div></section>`;}
function senseiChecks(){return `<div class="info-panel"><h2>Conferências práticas do sensei</h2><p>Depois das quatro fases digitais, o módulo pede uma observação prática para liberar o seguinte. O registro é feito pela conta de administrador e não equivale à graduação real do dojo.</p><div class="sensei-checks">${C.COURSE.filter(m=>m.requiresSensei).map(m=>{const ready=C.moduleQuizPassed(state.learning,m.id),approval=state.learning.approvals[m.id];return `<article><h3>${m.level}. ${m.title}</h3><ul>${m.practical.map(p=>`<li>${p}</li>`).join('')}</ul>${approval?`<p class="approval-ok">✓ Conferência registrada em ${new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeZone:G.RULES.timezone}).format(approval.at)}</p><p>${esc(approval.note)}</p>`:ready?`<label class="checkbox-label"><input type="checkbox" data-confirm-observed="${m.id}"> Observei a prática e as correções acima.</label><label>Retorno ao aluno (opcional)<input maxlength="300" data-approval-note="${m.id}" placeholder="Um ponto que melhorou e um ponto para continuar treinando"></label><button class="outline" data-approve-module="${m.id}">Registrar conferência e liberar próximo módulo</button>`:'<p class="week-note">Aguardando a aprovação nas quatro fases digitais.</p>'}</article>`;}).join('')}</div></div>`;}
async function saveMaterial(event){event.preventDefault();if(!DojoAccounts.canManage()){toast("A edição é exclusiva da conta de administrador.");return;}const status=$('#media-form-status'),button=event.submitter||$('#media-form button[type="submit"]');const id=$('#media-phase').value;if(!mediaTarget(id))return;const raw=$('#media-youtube').value.trim(),video=$('#media-video').files[0],image=$('#media-image').files[0];const title=$('#media-title').value.trim()||'Material do sensei',description=$('#media-description').value.trim();const fail=msg=>{status.textContent=msg;status.className='form-error';};if(raw&&video)return fail('Escolha um link ou um arquivo de vídeo por vez. A imagem pode acompanhar os dois.');if(!raw&&!video&&!image)return fail('Adicione um link, um vídeo ou uma imagem.');const youtubeId=raw?parseYouTube(raw):null;if(raw&&!youtubeId)return fail('Use um link HTTPS válido do YouTube ou youtu.be.');if(video&&(!/\.(mp4|webm)$/i.test(video.name)||!['video/mp4','video/webm',''].includes(video.type)||video.size>250*1024*1024))return fail('Use MP4 ou WebM de até 250 MB.');if(image&&(!['image/jpeg','image/png','image/webp'].includes(image.type)||image.size>12*1024*1024))return fail('Use PNG, JPG ou WebP de até 12 MB.');button.disabled=true;status.textContent='Salvando material…';status.className='';try{if(DojoAccounts.configured){state.media=await DojoAccounts.saveMaterial(id,{title,description,youtubeId},video,image);libraryModule=mediaTarget(id).module.id;libraryPhase=id;render("library");toast("Material salvo e disponível para os alunos.");return;}const old=state.media[id]||{};let entry={...old,title,description};let persisted=true;if(youtubeId){entry.youtubeId=youtubeId;entry.videoKey=null;}if(video){entry.videoKey=`${id}-video`;persisted=await DojoMedia.put(entry.videoKey,video)&&persisted;entry.youtubeId=null;}if(image){entry.imageKey=`${id}-image`;persisted=await DojoMedia.put(entry.imageKey,image)&&persisted;}entry.sessionOnly=!persisted;state.media[id]=entry;libraryModule=mediaTarget(id).module.id;libraryPhase=id;save();render('library');toast(persisted?'Material salvo neste navegador e vinculado à fase.':'O navegador não permitiu salvar o arquivo. Ele ficará disponível apenas nesta sessão.');}catch{fail('Não foi possível salvar. Tente um arquivo menor ou um link do YouTube.');}finally{if(button.isConnected)button.disabled=false;}}
function exportLinks(){const materials=Object.fromEntries(Object.entries(state.media).filter(([,v])=>v.youtubeId).map(([id,v])=>[id,{title:v.title,description:v.description,youtubeId:v.youtubeId}]));const blob=new Blob([JSON.stringify({format:'san-dojo-links-v1',materials},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='san-dojo-meus-links.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importLinks(file){if(!DojoAccounts.canManage()){toast("Somente o administrador pode importar materiais.");return;}try{if(!file||file.size>1024*1024)throw new Error();const data=JSON.parse(await file.text());if(data.format!=='san-dojo-links-v1'||typeof data.materials!=='object'||data.materials===null)throw new Error();let count=0;for(const [id,v]of Object.entries(data.materials)){if(!mediaTarget(id)||!v||!/^[A-Za-z0-9_-]{11}$/.test(v.youtubeId||''))continue;const fields={title:String(v.title||'Material do sensei').slice(0,80),description:String(v.description||'').slice(0,300),youtubeId:v.youtubeId};if(DojoAccounts.configured)state.media=await DojoAccounts.saveMaterial(id,fields);else state.media[id]=fields;count++;}save();render('library');toast(`${count} link(s) importado(s).`);}catch{toast('Arquivo inválido. Use uma exportação de links do San Dojo de até 1 MB.');}}
